<?php
require_once __DIR__ . '/common.php'; admin_require_login();
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT * FROM orders WHERE id=?');$stmt->execute([$id]);$order=$stmt->fetch(PDO::FETCH_ASSOC);if(!$order){admin_flash('Order not found.','error');header('Location: orders.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 admin_csrf_check();$orderStatus=$_POST['order_status']??$order['order_status'];$paymentStatus=$_POST['payment_status']??$order['payment_status'];$orderOptions=admin_column_enum_values($pdo,'orders','order_status');$paymentOptions=admin_column_enum_values($pdo,'orders','payment_status');
 if(($orderOptions&&!in_array($orderStatus,$orderOptions,true))||($paymentOptions&&!in_array($paymentStatus,$paymentOptions,true))){admin_flash('Invalid status selected.','error');header('Location: order-view.php?id='.$id);exit;}
 try{$stmt=$pdo->prepare('UPDATE orders SET order_status=?, payment_status=? WHERE id=?');$stmt->execute([$orderStatus,$paymentStatus,$id]);admin_flash('Order status updated.');header('Location: order-view.php?id='.$id);exit;}catch(Throwable $e){admin_flash('Could not update status. Check the allowed database status values.','error');header('Location: order-view.php?id='.$id);exit;}
}
$items=[];try{$stmt=$pdo->prepare('SELECT product_name, quantity, unit_price, line_total FROM order_items WHERE order_id=?');$stmt->execute([$id]);$items=$stmt->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){}
$orderOptions=admin_column_enum_values($pdo,'orders','order_status');$paymentOptions=admin_column_enum_values($pdo,'orders','payment_status');if(!$orderOptions)$orderOptions=[$order['order_status']];if(!$paymentOptions)$paymentOptions=[$order['payment_status']];
admin_render_start('Order details');echo '<div class="back-row"><a class="text-link" href="orders.php">← Back to orders</a><span class="pill">'.admin_e($order['order_number']).'</span></div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Customer details</h2><p>Order #'.admin_e($order['order_number']).'</p></div></div><dl class="details">';foreach(['customer_name'=>'Name','email'=>'Email','phone'=>'Phone','address'=>'Address','city'=>'City','state'=>'State','postal_code'=>'Postal code','payment_method'=>'Payment method','created_at'=>'Placed on'] as $key=>$label)echo '<div><dt>'.admin_e($label).'</dt><dd>'.nl2br(admin_e($order[$key]??'—')).'</dd></div>';echo '</dl></section><section class="panel"><div class="panel-head"><div><h2>Order summary</h2><p>Amounts recorded for this order</p></div></div><dl class="details"><div><dt>Subtotal</dt><dd>₹'.number_format((float)$order['subtotal'],2).'</dd></div><div><dt>Shipping</dt><dd>₹'.number_format((float)$order['shipping_fee'],2).'</dd></div><div><dt>Total</dt><dd><strong>₹'.number_format((float)$order['total'],2).'</strong></dd></div></dl><form method="post" class="admin-form status-form"><input type="hidden" name="csrf_token" value="'.admin_e(admin_csrf_token()).'"><label>Order status</label><select name="order_status">';foreach($orderOptions as $v)echo '<option value="'.admin_e($v).'" '.($v===$order['order_status']?'selected':'').'>'.admin_e(ucwords(str_replace('_',' ',$v))).'</option>';echo '</select><label>Payment status</label><select name="payment_status">';foreach($paymentOptions as $v)echo '<option value="'.admin_e($v).'" '.($v===$order['payment_status']?'selected':'').'>'.admin_e(ucwords(str_replace('_',' ',$v))).'</option>';echo '</select><button class="btn primary" type="submit">Update status</button></form></section></div><section class="panel"><div class="panel-head"><div><h2>Items ordered</h2><p>Products in this purchase</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Line total</th></tr></thead><tbody>';if(!$items)echo '<tr><td colspan="4" class="empty">No item details found for this order.</td></tr>';foreach($items as $it)echo '<tr><td>'.admin_e($it['product_name']).'</td><td>'.(int)$it['quantity'].'</td><td>₹'.number_format((float)$it['unit_price'],2).'</td><td>₹'.number_format((float)$it['line_total'],2).'</td></tr>';echo '</tbody></table></div></section>';admin_render_end();
